-- ============================================================
-- SEED EXT 3: Módulo 13 — Reported Speech (ex 143-215)
-- Novos tópicos: reporting verbs (claim/argue/deny/warn/urge),
-- perguntas e imperativas indiretas, no-backshift contexts, TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'reported-speech';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo reported-speech não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 31: reporting verbs — claim / argue / suggest / maintain
  (cid,31,143,'gap_fill','The author _____ (argue) that economic growth and environmental sustainability are not mutually exclusive.','argues',NULL,'"Argue + that-clause" = reporting an opinion or position (neutral academic).','easy'),
  (cid,31,144,'multiple_choice','Which reporting verb correctly describes a polite suggestion?','She suggested that they conduct further research before drawing conclusions.','["She argued that they conduct further research.","She demanded that they conduct further research.","She suggested that they conduct further research before drawing conclusions.","She claimed that they conduct further research."]','"Suggest + that + subjunctive" = polite suggestion.','medium'),
  (cid,31,145,'gap_fill','The professor _____ (maintain) that the traditional interpretation of the data is fundamentally flawed.','maintained / maintains',NULL,'"Maintain" = reporting a persistent, defended position.','medium'),
  (cid,31,146,'multiple_choice','Which reporting verb implies that the speaker is making an assertion others may doubt?','She claimed to have discovered a previously unknown species.','["She said she discovered a species.","She claimed to have discovered a previously unknown species.","She suggested she had discovered a species.","She admitted she had discovered a species."]','"Claim" = assert something that may be unverified or controversial.','medium'),
  (cid,31,147,'gap_fill','Critics _____ (contend) that the methodology used in the study is unsuitable for drawing causal conclusions.','contend',NULL,'"Contend" = argue strongly against a position (academic debate verb).','hard'),

  -- BLOCK 32: reporting verbs — deny / warn / urge / remind / accuse
  (cid,32,148,'gap_fill','The company _____ (deny) having disclosed confidential data to competitors.','denied',NULL,'"Deny + -ing" = report a denial of an action (not: deny + to + infinitive).','hard'),
  (cid,32,149,'multiple_choice','Which sentence correctly uses "warn"?','The doctor warned the patient not to ignore the symptoms.','["The doctor warned the patient to not ignore the symptoms (split infinitive — avoid).","The doctor warned the patient not to ignore the symptoms.","The doctor warned the patient about ignoring the symptoms (also acceptable).","The doctor warned that the patient will ignore the symptoms."]','"Warn + object + not + to + infinitive" = advise against a danger.','medium'),
  (cid,32,150,'gap_fill','The committee _____ (urge) researchers to adhere strictly to ethical guidelines in all stages of data collection.','urged',NULL,'"Urge + object + to + infinitive" = strongly recommend/pressure to do.','medium'),
  (cid,32,151,'multiple_choice','Which reporting verb is used for ACCUSING someone of wrongdoing?','The board accused the executive of falsifying the financial reports.','["The board argued the executive falsified the financial reports.","The board accused the executive of falsifying the financial reports.","The board suggested the executive falsified the financial reports.","The board reminded the executive to falsify the reports."]','"Accuse + object + of + -ing" = reporting blame for wrongdoing.','medium'),
  (cid,32,152,'gap_fill','The supervisor _____ (remind) the students to back up their data regularly.','reminded',NULL,'"Remind + object + to + infinitive" = report a reminder.','easy'),

  -- BLOCK 33: perguntas em reported speech
  (cid,33,153,'gap_fill','Direct: "Where did the outbreak begin?" → Reported: The epidemiologist asked _____ (where the outbreak had begun).','where the outbreak had begun',NULL,'Indirect question: no inversion, past perfect backshift.','hard'),
  (cid,33,154,'multiple_choice','Which correctly converts a yes/no question into reported speech? Direct: "Are you familiar with the methodology?"','She asked whether/if I was familiar with the methodology.','["She asked if was I familiar with the methodology.","She asked whether was I familiar with the methodology.","She asked whether/if I was familiar with the methodology.","She asked that I was familiar with the methodology."]','Yes/no indirect question: whether/if + subject + verb (no inversion).','hard'),
  (cid,33,155,'gap_fill','Direct: "How long have you been conducting this research?" → Reported: She asked _____ (how long) he had been conducting the research.','how long',NULL,'Reported question with "how long" — no inversion, backshift to past perfect.','medium'),
  (cid,33,156,'multiple_choice','In indirect questions, the verb is:','In statement word order (subject + verb), not question inversion.','["Inverted as in direct questions","In statement word order (subject + verb), not question inversion.","Always passive","Always past tense"]','Indirect question = statement order. "She asked what he had done" — not "what had he done."','hard'),
  (cid,33,157,'gap_fill','Direct: "Did you complete the required training?" → Reported: The manager asked _____ (whether) I had completed the required training.','whether / if',NULL,'"Whether/if" introduces yes/no indirect question.','medium'),

  -- BLOCK 34: imperativas e pedidos indiretos
  (cid,34,158,'gap_fill','Direct: "Please submit your application by Friday." → Reported: She _____ (asked/told) me to submit my application by Friday.','asked / told',NULL,'"Tell/ask + object + to + infinitive" = positive imperative in reported speech.','easy'),
  (cid,34,159,'multiple_choice','Which correctly converts a negative imperative? Direct: "Don''t touch the equipment!"','He told us not to touch the equipment.','["He told us to not touch the equipment (split infinitive — avoid).","He told us don''t touch the equipment.","He told us not to touch the equipment.","He told us that we shouldn''t touching the equipment."]','"Tell + object + not to + infinitive" = negative imperative in reported speech.','medium'),
  (cid,34,160,'gap_fill','Direct: "You should reconsider your methodology." → Reported: She _____ (advise) him to reconsider his methodology.','advised',NULL,'"Advise + object + to + infinitive" = report advice in indirect speech.','medium'),
  (cid,34,161,'multiple_choice','Which reporting verb pattern is correct: "The professor _____ publishing the results before peer review was complete"?','The professor warned against publishing the results before peer review was complete.','["The professor warned to publish the results before peer review was complete.","The professor advised not publish the results before peer review was complete.","The professor warned against publishing the results before peer review was complete.","The professor warned that to publish before peer review is complete."]','"Warn against + -ing" = advise strongly against an action.','hard'),

  -- BLOCK 35: contextos sem backshift (no-backshift)
  (cid,35,162,'multiple_choice','When is backshift NOT required in reported speech?','When the statement is still true at the time of reporting.','["When the verb is in the present tense","When the statement is still true at the time of reporting.","When reporting in academic writing","When the direct speech uses ''will''"]','No backshift required for universal truths/facts still valid: "He said the earth is round."','hard'),
  (cid,35,163,'gap_fill','Direct: "The data suggests a correlation." → Reported: The researcher noted that the data _____ (suggest/suggests) a correlation. (Still true)','suggests / suggested',NULL,'When the fact is still current, no backshift is required: "suggests" or "suggested" are both acceptable.','hard'),
  (cid,35,164,'multiple_choice','Which sentence demonstrates CORRECT no-backshift in reported speech?','The teacher explained that water consists of hydrogen and oxygen.','["The teacher explained that water consisted of hydrogen and oxygen (backshift used — also acceptable but less preferred for universal truths).","The teacher explained that water consists of hydrogen and oxygen.","The teacher explained water consists of hydrogen and oxygen (missing ''that'' — informal).","The teacher explained that water consisted of hydrogen and oxygen consisted of hydrogen and oxygen."]','Universal scientific fact: no backshift preferred. "Consists" is still true.','hard'),
  (cid,35,165,'gap_fill','Academic papers often avoid full backshift when reporting _____ (findings / results) that are still considered valid.','findings / results / conclusions',NULL,'When reporting current research findings, both backshift and no-backshift are acceptable in academic writing.','medium'),

  -- BLOCK 36: TOEFL Reading
  (cid,36,166,'multiple_choice','[TOEFL Reading] "The author contends that the existing framework fails to account for cultural variation." The word "contends" signals:','The author is defending a contested position.','["A neutral description","An admission of error","The author is defending a contested position.","A direct quotation"]','"Contend" = report a strongly held, contested argument.','medium'),
  (cid,36,167,'gap_fill','[TOEFL Reading] "The scientist reported that the experiment _____ (produce) unexpected results in all three trials." Best form?','had produced / produced',NULL,'Reported speech: past simple → past perfect (or past simple stays).','medium'),
  (cid,36,168,'multiple_choice','[TOEFL Reading] "Critics have argued that the policy ignores structural causes of poverty." The present perfect "have argued" in reported speech indicates:','The argument has been made and remains relevant (not fully in the past).','["A backshift from past perfect","The argument has been made and remains relevant (not fully in the past).","Present perfect is incorrect in reported speech","The argument was made once and is now obsolete"]','Present perfect in reporting = ongoing critical debate.','hard'),
  (cid,36,169,'gap_fill','[TOEFL Reading] "Researchers warned _____ (against) relying too heavily on self-reported data." Complete with the correct preposition.','against',NULL,'"Warn against + -ing" = advise strongly against an action.','medium'),

  -- BLOCK 37: TOEFL Speaking
  (cid,37,170,'production','[TOEFL Speaking — 45s] A reading discusses a controversy over a scientific study. Summarize the key claims and counter-claims using: argued, claimed, contended, denied, warned, suggested.','',NULL,'The article describes a heated debate over a recent study on the health effects of processed foods. The study''s authors argued that consumption of ultra-processed foods is directly linked to increased cancer risk. However, food industry representatives claimed that the methodology was flawed and that the results do not demonstrate causation. An independent statistician contended that the sample size was insufficient to support the strong conclusions drawn. The original research team denied that any undisclosed conflicts of interest had influenced their analysis. Nutrition experts warned against dismissing the study entirely, while others suggested that a larger replication study would be needed before any public health recommendations could be made.','hard'),
  (cid,37,171,'production','[TOEFL Speaking — 45s] A professor and a student disagree about the best way to address academic dishonesty. Report both positions. Use: argued, suggested, urged, admitted, denied, contended, asked.','',NULL,'The professor argued that academic dishonesty should result in automatic failure for the course, not merely a warning. The student, however, contended that first offenses should be handled educationally rather than punitively. She suggested that universities should invest in honor code education before resorting to strict penalties. The professor admitted that preventive programs have merit but urged that consistency in enforcement is equally essential. When the professor asked whether the student had ever witnessed unreported cheating, she denied any direct knowledge but acknowledged that the topic is rarely discussed openly among peers.','hard'),

  -- BLOCK 38: TOEFL Writing
  (cid,38,172,'production','[TOEFL Writing — 150 words] Write an academic paragraph synthesizing different scholarly positions on online education. Use: argue/argued, suggest, claim/claimed, maintain, contend, warn, note, with accurate indirect speech grammar.','',NULL,'Scholars hold diverse and often conflicting views on the long-term impact of online education. Proponents argue that digital platforms democratize access to high-quality instruction, enabling learners in remote or low-income contexts to participate in courses that were previously out of reach. Some researchers even claim that online learning, when well-designed, can be as effective as face-to-face instruction for certain types of content. Others contend that this view is overly optimistic: educational technologists warn that the benefits of online learning are heavily mediated by digital literacy, reliable internet access, and self-regulation skills that many students lack. A growing body of research suggests that hybrid models — combining digital flexibility with in-person interaction — may represent the most effective compromise. Educators note that the quality of the pedagogy, rather than the medium of delivery, is ultimately what determines learning outcomes.','hard'),
  (cid,38,173,'production','[TOEFL Writing — Error Correction] Fix reported speech errors: "She said me that she will finish the report. He asked where did the data come from. They denied to have fabricated the results. The professor told that students should attend. She suggested to reconsider the approach."','',NULL,'said me → told me (say + that-clause; tell + object + that-clause); will finish → would finish (backshift: will → would); where did the data come from → where the data came from (indirect question: no inversion, no auxiliary); denied to have → denied having (deny + -ing, not to-infinitive); told that students should attend → told students that they should attend (tell needs an object) OR said that students should attend; suggested to reconsider → suggested reconsidering / suggested that they reconsider (suggest + -ing or suggest + that + subjunctive, not to-infinitive).','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
